import React, { useState } from 'react';
import { createStore3Return } from '../../services/stockService';

const ReturnOperations = () => {
    const [error, setError] = useState(null);
    const [returnForm, setReturnForm] = useState({
        saleId: '',
        productId: '',
        quantity: 0,
        customerName: '',
        customerPhone: '',
        returnReason: '',
        refundAmount: 0
    });

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await createStore3Return(returnForm);
            if (response.success) {
                alert('İade başarıyla oluşturuldu');
                setReturnForm({
                    saleId: '',
                    productId: '',
                    quantity: 0,
                    customerName: '',
                    customerPhone: '',
                    returnReason: '',
                    refundAmount: 0
                });
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('İade oluşturulurken bir hata oluştu');
        }
    };

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Store 3 - İade İşlemleri</h1>

            {/* İade Oluşturma Formu */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Yeni İade Oluştur</h2>
                {error && (
                    <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                        {error}
                    </div>
                )}
                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input
                        type="text"
                        placeholder="Satış ID"
                        className="border p-2 rounded"
                        value={returnForm.saleId}
                        onChange={(e) => setReturnForm({...returnForm, saleId: e.target.value})}
                        required
                    />
                    <input
                        type="text"
                        placeholder="Ürün ID"
                        className="border p-2 rounded"
                        value={returnForm.productId}
                        onChange={(e) => setReturnForm({...returnForm, productId: e.target.value})}
                        required
                    />
                    <input
                        type="number"
                        placeholder="İade Miktarı"
                        className="border p-2 rounded"
                        value={returnForm.quantity}
                        onChange={(e) => setReturnForm({...returnForm, quantity: parseInt(e.target.value)})}
                        required
                        min="1"
                    />
                    <input
                        type="text"
                        placeholder="Müşteri Adı"
                        className="border p-2 rounded"
                        value={returnForm.customerName}
                        onChange={(e) => setReturnForm({...returnForm, customerName: e.target.value})}
                        required
                    />
                    <input
                        type="text"
                        placeholder="Müşteri Telefonu"
                        className="border p-2 rounded"
                        value={returnForm.customerPhone}
                        onChange={(e) => setReturnForm({...returnForm, customerPhone: e.target.value})}
                        required
                    />
                    <input
                        type="number"
                        placeholder="İade Tutarı"
                        className="border p-2 rounded"
                        value={returnForm.refundAmount}
                        onChange={(e) => setReturnForm({...returnForm, refundAmount: parseFloat(e.target.value)})}
                        required
                        min="0"
                        step="0.01"
                    />
                    <textarea
                        placeholder="İade Nedeni"
                        className="border p-2 rounded md:col-span-2"
                        value={returnForm.returnReason}
                        onChange={(e) => setReturnForm({...returnForm, returnReason: e.target.value})}
                        required
                        rows="4"
                    />
                    <button type="submit" className="bg-yellow-500 text-white p-2 rounded hover:bg-yellow-600 md:col-span-2">
                        İade Oluştur
                    </button>
                </form>
            </div>
        </div>
    );
};

export default ReturnOperations;
